-- PKG_SYS0014 — META 전환 확인 (조회 전용)
SET PAGESIZE 200 LINESIZE 300

-- P_SYS0014_GET_AUTH_LIST_M → PKG_SYS0014.P_SYS0014_GET_AUTH_LIST_M
SELECT API_ID, API_URL, CASE WHEN API_URL = 'PKG_SYS0014.P_SYS0014_GET_AUTH_LIST_M' THEN 'OK' ELSE 'NG' END CHK FROM SCM_MGR.SCM_ADM_API_M WHERE API_ID IN ('API_SYS0014_GET_AUTH_LIST');
SELECT 'PKG_SYS0014.P_SYS0014_GET_AUTH_LIST_M' PROC_NM,
       (SELECT COUNT(*) FROM SCM_MGR.SCM_ADM_PROC_M WHERE PROC_NM = 'PKG_SYS0014.P_SYS0014_GET_AUTH_LIST_M') NEW_ROWS,
       (SELECT COUNT(*) FROM SCM_MGR.SCM_ADM_PROC_M WHERE UPPER(PROC_NM) = 'P_SYS0014_GET_AUTH_LIST_M') STANDALONE_ROWS,
       (SELECT COUNT(*) FROM USER_ARGUMENTS WHERE PACKAGE_NAME = 'PKG_SYS0014' AND OBJECT_NAME = 'P_SYS0014_GET_AUTH_LIST_M' AND DATA_LEVEL = 0) MEMBER_ARGS,
       (SELECT LISTAGG(COL_TP_CD, ',') WITHIN GROUP (ORDER BY SORT_ORD) FROM SCM_MGR.SCM_ADM_PROC_M WHERE PROC_NM = 'PKG_SYS0014.P_SYS0014_GET_AUTH_LIST_M') PROC_M_INOUT,
       (SELECT LISTAGG(REPLACE(IN_OUT, 'IN/OUT', 'INOUT'), ',') WITHIN GROUP (ORDER BY POSITION) FROM USER_ARGUMENTS WHERE PACKAGE_NAME = 'PKG_SYS0014' AND OBJECT_NAME = 'P_SYS0014_GET_AUTH_LIST_M' AND DATA_LEVEL = 0) MEMBER_INOUT
  FROM DUAL;

